"""V2 COPY of combine.py: reads data/training/pairs_v2.csv (corrected labels) and writes only to results_v2/. Generated by make_v2_scripts.py; do not edit."""
"""Combine current_stage2 and the cross-encoder using only existing out-of-fold scores.

No retraining. Inputs: results/baseline_scores.csv (current_stage2), results/ce_scores.csv
(prob_mean), folds already in those files. Real rows, label != -1. For each held-out fold k,
anything fitted (stacker weights, thresholds) uses the OTHER three folds' OOF rows only.
Writes results/combine.md and results/combine_scores.csv. Inputs are never modified.

Caveat (inherent to stacking OOF scores): the cross-encoder OOF scores of the training folds
came from models that had seen fold k's labels, so the stacker is not perfectly independent
of fold k.
"""
from pathlib import Path

from report_header import insert_header, labels_header  # run header for the report (captions only)
import numpy as np
import pandas as pd
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler

HERE = Path(__file__).resolve().parent
OUT = HERE / "results_v2"
N_BOOT, SEED, STAGE2_T = 1000, 0, 0.65
BANDS = [(0.35, 0.80), (0.45, 0.75), (0.50, 0.70)]

# ---------------- load ----------------
base = pd.read_csv(OUT / "baseline_scores.csv", dtype={"pair_id": str, "video_id": str})
ce = pd.read_csv(OUT / "ce_scores.csv", dtype={"pair_id": str, "video_id": str}).drop_duplicates("pair_id")
df = base[["pair_id", "video_id", "fold", "label", "current_stage2"]].merge(
    ce[["pair_id", "prob_mean"]].rename(columns={"prob_mean": "ce"}), on="pair_id", validate="1:1")
assert len(df) == len(base) == len(ce) and df.notna().all().all()
# gap_units: segment-number difference between the two units, from pair_id "<video>__<seg>-<sub>__<seg>-<sub>"
parts = df.pair_id.str.split("__", expand=True)
df["gap_units"] = parts[2].map(lambda s: int(s.split("-")[0])) - parts[1].map(lambda s: int(s.split("-")[0]))
df["ce_logit"] = np.log(np.clip(df.ce, 1e-6, 1 - 1e-6) / (1 - np.clip(df.ce, 1e-6, 1 - 1e-6)))
y = df.label.values
folds = sorted(df.fold.unique())

# prior Stage 2 errors (for fixed / new comparison)
s2_pred = (df.current_stage2 >= STAGE2_T).astype(int).values


# ---------------- helpers ----------------
def best_f1_threshold(yt, s):
    """Threshold maximising F1 on (yt, s); predict positive when score >= threshold."""
    prec, rec, thr = precision_recall_curve(yt, s)
    f1 = 2 * prec[:-1] * rec[:-1] / np.clip(prec[:-1] + rec[:-1], 1e-12, None)
    return float(thr[np.argmax(f1)])


def prf(yt, pred):
    tp = int(((pred == 1) & (yt == 1)).sum())
    p = tp / pred.sum() if pred.sum() else 0.0
    r = tp / (yt == 1).sum() if (yt == 1).sum() else 0.0
    return p, r, (2 * p * r / (p + r) if p + r else 0.0)


def recall_at_precision(yt, s, p):
    prec, rec, _ = precision_recall_curve(yt, s)
    ok = prec >= p
    return float(rec[ok].max()) if ok.any() else 0.0


def rank_metrics(yt, s):
    return {"PR-AUC": average_precision_score(yt, s), "ROC-AUC": roc_auc_score(yt, s),
            "R@P90": recall_at_precision(yt, s, 0.90), "R@P80": recall_at_precision(yt, s, 0.80)}


score = {}      # method -> score array (higher = more likely retake)
pred = {}       # method -> binary decision at the (fold-chosen) threshold
coefs = []

# reference methods
score["current_stage2"] = df.current_stage2.values
pred["current_stage2"] = s2_pred                               # fixed 0.65
score["cross_encoder"] = df.ce.values
pred["cross_encoder"] = np.zeros(len(df), int)

# ---------------- 1/2: stackers ----------------
for name, feats in [("stack", ["current_stage2", "ce_logit"]), ("stack_gap", ["current_stage2", "ce_logit", "gap_units"])]:
    score[name], pred[name] = np.zeros(len(df)), np.zeros(len(df), int)
    for k in folds:
        te = (df.fold == k).values
        m = make_pipeline(StandardScaler(), LogisticRegression(class_weight="balanced", max_iter=2000))
        m.fit(df.loc[~te, feats], y[~te])
        score[name][te] = m.predict_proba(df.loc[te, feats])[:, 1]
        # decision threshold chosen on the training folds' (in-sample) stacker scores
        t = best_f1_threshold(y[~te], m.predict_proba(df.loc[~te, feats])[:, 1])
        pred[name][te] = (score[name][te] >= t).astype(int)
        for f, c in zip(feats, m[-1].coef_[0]):                # standardized coefficients
            coefs.append({"method": name, "fold": k, "feature": f, "coef": c, "threshold": t})

# ---------------- 4: rank average (no fitting) ----------------
# percentile ranks over all pooled OOF rows (label-free); threshold chosen on training folds
rs2, rce = df.current_stage2.rank(pct=True).values, df.ce.rank(pct=True).values
score["rank_avg"] = (rs2 + rce) / 2
pred["rank_avg"] = np.zeros(len(df), int)
for k in folds:
    te = (df.fold == k).values
    t = best_f1_threshold(y[~te], score["rank_avg"][~te])
    pred["rank_avg"][te] = (score["rank_avg"][te] >= t).astype(int)
# cross-encoder alone, with a train-chosen threshold (reference)
for k in folds:
    te = (df.fold == k).values
    pred["cross_encoder"][te] = (df.ce.values[te] >= best_f1_threshold(y[~te], df.ce.values[~te])).astype(int)

# ---------------- 3: cascade ----------------
s2, cev = df.current_stage2.values, df.ce.values


def cascade_pred(mask, lo, hi, t):
    """Outside the band keep Stage 2's decision (above hi -> 1, below lo -> 0); inside use ce >= t."""
    in_band = (s2[mask] >= lo) & (s2[mask] <= hi)
    return np.where(in_band, cev[mask] >= t, s2[mask] > hi).astype(int)


cascade_info = {}
for lo, hi in BANDS:
    name = f"cascade_{lo}_{hi}"
    pred[name], score[name] = np.zeros(len(df), int), np.zeros(len(df))
    for k in folds:
        te = (df.fold == k).values
        tr_idx = np.where(~te)[0]
        in_band_tr = (s2[tr_idx] >= lo) & (s2[tr_idx] <= hi)
        cands = np.unique(cev[tr_idx][in_band_tr])
        # threshold maximising the CASCADE's F1 on the training folds
        f1s = [prf(y[tr_idx], cascade_pred(tr_idx, lo, hi, t))[2] for t in cands]
        t = float(cands[int(np.argmax(f1s))])
        pred[name][te] = cascade_pred(np.where(te)[0], lo, hi, t)
        cascade_info[(name, k)] = t
    # surrogate ranking score consistent with the decisions (for PR-AUC etc.):
    # tier 3 above band (by s2), tier 2 in band & ce>=t (by ce), tier 1 in band & ce<t (by ce), tier 0 below band.
    for k in folds:
        te = (df.fold == k).values
        t = cascade_info[(name, k)]
        in_band = (s2 >= lo) & (s2 <= hi)
        tier = np.where(s2 > hi, 3, np.where(in_band, np.where(cev >= t, 2, 1), 0))
        val = np.where(in_band, cev, s2)
        score[name][te] = (tier * 10 + val)[te]

METHODS = list(score)
for m in METHODS:
    df["score_" + m], df["pred_" + m] = score[m], pred[m]

# ---------------- metrics ----------------
scopes = [("pooled", np.ones(len(df), bool))] + [(f"fold{k}", (df.fold == k).values) for k in folds]
rank_res = {(m, s): rank_metrics(y[msk], score[m][msk]) for m in METHODS for s, msk in scopes}
dec_res = {(m, s): prf(y[msk], pred[m][msk]) for m in METHODS for s, msk in scopes}

# paired video-level bootstrap of PR-AUC difference vs current_stage2
rng = np.random.default_rng(SEED)
vids = df.video_id.unique()
idx_by_vid = {v: np.where(df.video_id.values == v)[0] for v in vids}
boot = {m: [] for m in METHODS}
for _ in range(N_BOOT):
    idx = np.concatenate([idx_by_vid[v] for v in rng.choice(vids, len(vids), replace=True)])
    for m in METHODS:
        boot[m].append(average_precision_score(y[idx], score[m][idx]) if y[idx].sum() else np.nan)
boot = {m: np.array(v) for m, v in boot.items()}
diffs = {}
for m in METHODS:
    if m == "current_stage2":
        continue
    d = boot[m] - boot["current_stage2"]
    lo_, hi_ = np.nanpercentile(d, [2.5, 97.5])
    diffs[m] = (rank_res[(m, "pooled")]["PR-AUC"] - rank_res[("current_stage2", "pooled")]["PR-AUC"], lo_, hi_)

# ---------------- errors: fixed vs new relative to Stage 2 @0.65 ----------------
def err_counts(m, msk):
    p = pred[m][msk]; yy = y[msk]; sp = s2_pred[msk]
    return {"fixed_FN": int(((yy == 1) & (sp == 0) & (p == 1)).sum()), "fixed_FP": int(((yy == 0) & (sp == 1) & (p == 0)).sum()),
            "new_FN": int(((yy == 1) & (sp == 1) & (p == 0)).sum()), "new_FP": int(((yy == 0) & (sp == 0) & (p == 1)).sum()),
            "FN": int(((yy == 1) & (p == 0)).sum()), "FP": int(((yy == 0) & (p == 1)).sum())}


stage2_errs = pd.read_csv(OUT / "stage2_errors.csv", dtype=str)
assert (len(stage2_errs[stage2_errs.error == "FN"]), len(stage2_errs[stage2_errs.error == "FP"])) == (
    int(((y == 1) & (s2_pred == 0)).sum()), int(((y == 0) & (s2_pred == 1)).sum())), "stage2_errors.csv mismatch"

# ---------------- outputs ----------------
keep = ["pair_id", "video_id", "fold", "label", "current_stage2", "ce", "gap_units"] + \
       [c for m in METHODS for c in ("score_" + m, "pred_" + m)]
df[keep].to_csv(OUT / "combine_scores.csv", index=False)

sn = [s for s, _ in scopes]
md = ["# Combining Stage 2 and the cross-encoder", "",
      f"Only existing out-of-fold scores are used (no retraining): {len(df)} real rows, {int(y.sum())} positives. For each "
      "held-out fold the stacker weights and all thresholds are fitted on the other three folds' OOF rows. Decision metrics use "
      "the fold-chosen threshold (maximising F1 on the training folds), except current_stage2 which uses its fixed 0.65.", "",
      "Caveat: the cross-encoder OOF scores of the training folds came from models that saw the held-out fold's labels, "
      "so stacking is slightly optimistic. Cascade PR-AUC etc. use a tiered surrogate score consistent with its decisions. "
      "The three cascade bands are all reported; none was selected on test data.", ""]
for m_ in ["PR-AUC", "ROC-AUC", "R@P90", "R@P80"]:
    md += [f"### {m_}", "", "| method | " + " | ".join(sn) + " |", "|---|" + "---|" * len(sn)]
    md += [f"| {m} | " + " | ".join(f"{rank_res[(m, s)][m_]:.3f}" for s in sn) + " |" for m in METHODS]
    md.append("")
for i, nm in enumerate(["precision", "recall", "F1"]):
    md += [f"### {nm} at the fold-chosen threshold", "", "| method | " + " | ".join(sn) + " |", "|---|" + "---|" * len(sn)]
    md += [f"| {m} | " + " | ".join(f"{dec_res[(m, s)][i]:.3f}" for s in sn) + " |" for m in METHODS]
    md.append("")
md += ["### Paired video-level bootstrap: pooled PR-AUC minus current_stage2 (1000 resamples, seed 0)", "",
       "| method | diff | 95% CI | CI excludes 0 |", "|---|---|---|---|"]
md += [f"| {m} | {d:+.3f} | [{lo_:+.3f}, {hi_:+.3f}] | {lo_ > 0 or hi_ < 0} |" for m, (d, lo_, hi_) in diffs.items()]
md += ["", f"### Errors vs Stage 2 @0.65 (pooled; Stage 2 has {int(((y == 1) & (s2_pred == 0)).sum())} FN and {int(((y == 0) & (s2_pred == 1)).sum())} FP)", "",
       "| method | FN | FP | fixed FN | fixed FP | new FN | new FP |", "|---|---|---|---|---|---|---|"]
for m in METHODS:
    c = err_counts(m, np.ones(len(df), bool))
    md.append(f"| {m} | {c['FN']} | {c['FP']} | {c['fixed_FN']} | {c['fixed_FP']} | {c['new_FN']} | {c['new_FP']} |")
f3 = (df.fold == 3).values
md += ["", "### Fold 3 only (Group C + Group D)", "",
       "| method | PR-AUC | R@P90 | precision | recall | F1 | FN | FP | fixed FN | fixed FP | new FN | new FP |",
       "|---|---|---|---|---|---|---|---|---|---|---|---|"]
for m in METHODS:
    r, d_, c = rank_res[(m, "fold3")], dec_res[(m, "fold3")], err_counts(m, f3)
    md.append(f"| {m} | {r['PR-AUC']:.3f} | {r['R@P90']:.3f} | {d_[0]:.3f} | {d_[1]:.3f} | {d_[2]:.3f} | {c['FN']} | {c['FP']} | "
              f"{c['fixed_FN']} | {c['fixed_FP']} | {c['new_FN']} | {c['new_FP']} |")
cf = pd.DataFrame(coefs)
md += ["", "### Stacker coefficients per fold (on standardized features; ce_logit = logit of cross-encoder prob_mean)", ""]
for name in ["stack", "stack_gap"]:
    c = cf[cf.method == name]
    md += [f"**{name}**", "", "| feature | " + " | ".join(f"fold{k}" for k in folds) + " |", "|---|" + "---|" * len(folds)]
    for f in c.feature.unique():
        md.append(f"| {f} | " + " | ".join(f"{v:+.3f}" for v in c[c.feature == f].sort_values("fold").coef) + " |")
    md.append("")
md += ["Cascade thresholds chosen per fold (cross-encoder prob inside the band): " + "; ".join(
    f"{n}: " + ", ".join(f"f{k}={cascade_info[(n, k)]:.3f}" for k in folds) for n in [m for m in METHODS if m.startswith("cascade")]), ""]

best = max([m for m in METHODS if m not in ("current_stage2",)], key=lambda m: rank_res[(m, "pooled")]["PR-AUC"])
bestf1 = max([m for m in METHODS], key=lambda m: dec_res[(m, "pooled")][2])
d, lo_, hi_ = diffs[best]
md += ["## Summary", "",
       f"1. Best pooled PR-AUC: {best} {rank_res[(best, 'pooled')]['PR-AUC']:.3f} vs Stage 2 {rank_res[('current_stage2', 'pooled')]['PR-AUC']:.3f} "
       f"(diff {d:+.3f}, 95% CI [{lo_:+.3f}, {hi_:+.3f}], {'excludes' if lo_ > 0 or hi_ < 0 else 'includes'} 0).",
       f"2. Best pooled F1 at the fold-chosen threshold: {bestf1} {dec_res[(bestf1, 'pooled')][2]:.3f} vs Stage 2 {dec_res[('current_stage2', 'pooled')][2]:.3f}.",
       f"3. Fold 3 PR-AUC: Stage 2 {rank_res[('current_stage2', 'fold3')]['PR-AUC']:.3f}, cross-encoder {rank_res[('cross_encoder', 'fold3')]['PR-AUC']:.3f}, "
       f"best combination ({best}) {rank_res[(best, 'fold3')]['PR-AUC']:.3f}. Small per-fold gaps should not be over-read."]
(OUT / "combine.md").write_text(insert_header(md, labels_header(HERE / "pairs_v2.csv", HERE / "folds.json", len(df), int(df.label.sum()))), encoding="utf-8")
print("\n".join(md))
